const items = $input.all();
if (!items || items.length === 0) {
  return [{ json: { error: 'No data received', token_valid: false } }];
}

const firstItem = items[0].json;
const body = $('Webhook Trigger').item.json.body || {};
const plan  = body.edited_plan || {};
const action = (plan.action || '').toLowerCase();

// ── For login_user: no token required yet (user is authenticating) ──────────
if (action === 'login_user') {
  return [{
    json: {
      user_id:     '',
      email:       plan.email || '',
      name:        '',
      role:        'guest',
      token_valid: true,
      is_login_request: true
    }
  }];
}

const authHeader = firstItem.headers?.authorization || firstItem.headers?.Authorization || '';

if (!authHeader.startsWith('Bearer ')) {
  return [{ json: { error: 'Missing Authorization header', token_valid: false } }];
}

const token = authHeader.substring(7);
const parts = token.split('.');

try {
  // ── Standard JWT (3 parts) ────────────────────────────────────────────────
  if (parts.length === 3) {
    let payloadBase64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
    while (payloadBase64.length % 4 !== 0) payloadBase64 += '=';
    const decoded = JSON.parse(Buffer.from(payloadBase64, 'base64').toString('utf-8'));
    const bodyName = body.name || '';
    return [{
      json: {
        user_id:     decoded.sub    || decoded.oid || '',
        email:       decoded.upn    || decoded.preferred_username || decoded.email || '',
        name:        decoded.name   || bodyName || '',
        role:        decoded.role   || 'staff',
        roles:       decoded.roles  || ['employee'],
        tenant_id:   decoded.tid    || 'chinhin_hq',
        token_valid: true
      }
    }];
  }

  // ── Custom base64 token (App.jsx fakeToken: btoa(JSON+':'+timestamp)) ─────
  const raw = Buffer.from(token, 'base64').toString('utf-8');
  const colonIdx = raw.lastIndexOf(':');
  const jsonStr  = colonIdx > 0 ? raw.substring(0, colonIdx) : raw;
  const info = JSON.parse(jsonStr);
  return [{
    json: {
      user_id:     info.email || '',
      email:       info.email || '',
      name:        info.name  || '',
      role:        info.role  || 'staff',
      token_valid: true
    }
  }];

} catch (error) {
  return [{ json: { error: error.message, token_valid: false } }];
}

