// Log the audit_log object to console
for (const item of $input.all()) {
  if (item.json.audit_log) {
    console.log('Audit Log:', JSON.stringify(item.json.audit_log, null, 2));
  }
}

// Return items unchanged
return $input.all();

const incomingRequest = $('Webhook Trigger').item.json.body || {};
const aiResponse = $('Code (Parse JSON)').item.json;

let final_plan;
if (incomingRequest.confirm === true && incomingRequest.edited_plan) {
  final_plan = incomingRequest.edited_plan;
} else {
  final_plan = aiResponse.action_plan || {};
}

// Determine which sub to call
const action = (final_plan.action || '').toLowerCase();
let sub_target = final_plan.sub_target || aiResponse.sub_target || '';

if (!sub_target) {
  if (['book_meeting_room','create_calendar_event','update_event','cancel_event','get_bookings'].includes(action)) {
    sub_target = 'meeting_room';
  } else if (action.startsWith('visitor') || action.includes('register_visitor')) {
    sub_target = 'visitor';
  } else if (action.startsWith('wellness') || action.startsWith('health')) {
    sub_target = 'wellness';
  } else if (action.startsWith('transport') || action.startsWith('book_transport')) {
    sub_target = 'transport';
  } else if (action.startsWith('training') || action.startsWith('enroll')) {
    sub_target = 'training';
  } else if (action.startsWith('flexhr') || action.startsWith('leave') || action.startsWith('payroll') || action.startsWith('hr_')) {
    sub_target = 'flexhr';
  } else if (action.startsWith('ticket') || action.startsWith('support') || action.startsWith('it_')) {
    sub_target = 'ticketing';
  } else {
    sub_target = aiResponse.sub_target || 'unknown';
  }
}

return [{
  json: {
    ...aiResponse,
    final_plan:  final_plan,
    sub_target:  sub_target,
  }
}];

// Parse AI Agent JSON response safely
const raw = $input.first().json.output || '';
let parsed;
try {
  // Strip markdown code fences if AI wrapped in ```json
  const clean = raw.replace(/^```json\s*/i, '').replace(/```\s*$/,'').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  return [{ json: {
    intent: 'unknown',
    sub_target: 'unknown',
    needs_clarification: true,
    clarification_question: 'Sorry, I could not understand your request. Could you rephrase it?',
    needs_confirmation: false,
    action_plan: { action: 'unknown', sub_target: 'unknown', risk_level: 'low', parameters: {} }
  }}];
}

// Ensure sub_target exists — fallback derive from intent if AI missed it
if (!parsed.sub_target) {
  const action = (parsed.intent || parsed.action_plan?.action || '').toLowerCase();
  if (['book_meeting_room','create_calendar_event','update_event','cancel_event','get_bookings'].includes(action)) {
    parsed.sub_target = 'meeting_room';
  } else if (action.includes('visitor')) {
    parsed.sub_target = 'visitor';
  } else if (action.includes('wellness') || action.includes('health')) {
    parsed.sub_target = 'wellness';
  } else if (action.includes('transport')) {
    parsed.sub_target = 'transport';
  } else if (action.includes('training') || action.includes('enroll')) {
    parsed.sub_target = 'training';
  } else if (action.includes('leave') || action.includes('payslip') || action.includes('hr_') || action.includes('flexhr')) {
    parsed.sub_target = 'flexhr';
  } else if (action.includes('ticket') || action.includes('support')) {
    parsed.sub_target = 'ticketing';
  } else {
    parsed.sub_target = 'unknown';
  }
}

// Mirror sub_target into action_plan
if (parsed.action_plan) {
  parsed.action_plan.sub_target = parsed.action_plan.sub_target || parsed.sub_target;
}

return [{ json: parsed }];

// Direct action from any UI form.
// edited_plan is fully constructed — bypass AI Agent.
const body = $('Webhook Trigger').item.json.body || {};
const plan  = body.edited_plan || {};

if (!plan.action) {
  throw new Error('direct_action: edited_plan.action is missing');
}

// Determine which sub to call based on action prefix
const action = plan.action.toLowerCase();
let sub_target = plan.sub_target || ''; // allow explicit override

if (!sub_target) {
  if (['book_meeting_room','create_calendar_event','update_event','cancel_event','get_bookings'].includes(action)) {
    sub_target = 'meeting_room';
  } else if (action.startsWith('visitor') || action.includes('register_visitor')) {
    sub_target = 'visitor';
  } else if (action.startsWith('wellness') || action.startsWith('health')) {
    sub_target = 'wellness';
  } else if (action.startsWith('transport') || action.startsWith('book_transport')) {
    sub_target = 'transport';
  } else if (action.startsWith('training') || action.startsWith('enroll')) {
    sub_target = 'training';
  } else if (action.startsWith('flexhr') || action.startsWith('leave') || action.startsWith('payroll') || action.startsWith('hr_')) {
    sub_target = 'flexhr';
  } else if (plan.sub_target === 'auth' || ['login_user','list_users','create_user','update_user'].includes(action)) {
    sub_target = 'auth';
  } else if (action.startsWith('ticket') || action.startsWith('support') || action.startsWith('it_')) {
    sub_target = 'ticketing';
  } else {
    sub_target = 'unknown';
  }
}

return [{
  json: {
    intent:              action,
    needs_clarification: false,
    needs_confirmation:  false,
    final_plan:          plan,
    sub_target:          sub_target,
    user_email:          body.upn || body.id || $input.first().json.email || '',
    user_name:           body.name || $input.first().json.name || '',
    session_id:          body.session_id || '',
    employee_id:         (() => { try { return $('Upsert Employee').first().json.employee_id; } catch { return null; } })(),
  }
}];

const body = $input.first().json.body;

if (!body.audio_base64) {
    return [{ json: $input.first().json }];
}

let rawBase64 = body.audio_base64;
if (rawBase64.includes(',')) {
    rawBase64 = rawBase64.split(',')[1];
}

const binaryData = Buffer.from(rawBase64, 'base64');
const isAndroid = body.platform === 'android';

// TRICK: Kita tipu API Groq dengan menggunakan nama .wav
const ext = isAndroid ? 'wav' : 'webm';
const namaFail = `voice.${ext}`;
const jenisMime = isAndroid ? 'audio/wav' : 'audio/webm';

return [{
    json: $input.first().json,
    binary: {
        data: {
            data: binaryData.toString('base64'),
            mimeType: jenisMime,
            fileName: namaFail,
            fileExtension: ext
        }
    }
}];

// Merge the verified token data with the upserted employee_id
const verify = $('VerifyTempToken').first().json;
const empRow  = $input.first().json;

return [{
  json: {
    user_id:     empRow.employee_id || verify.user_id,
    email:       empRow.email       || verify.email,
    name:        empRow.employee_name || verify.name,
    roles:       verify.roles,
    tenant_id:   verify.tenant_id,
    token_valid: verify.token_valid,
  }
}];

const item = $input.first().json;
const result = item.result || item;
const data = result.data;
const action = result.action || item.action;

if (action === 'get_sessions' && Array.isArray(data) && data.length > 0) {
  const lines = data.map((s, i) => {
    const time = s.session_time
      ? new Date(s.session_time).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false })
      : '—';
    return `${i + 1}. Session #${s.session_id} – ${time}, ${s.from_location || '—'} → ${s.to_location || '—'} (${s.session_type || 'shuttle'})`;
  });
  const formattedMessage = `Found ${data.length} session(s):\n${lines.join('\n')}\n\nWhich session would you like to book? (Reply with the number or session ID)`;

  return [{
    json: {
      ...item,
      result: {
        ...result,
        message: formattedMessage,
        formatted_sessions: data.map(s => ({ session_id: s.session_id, session_time: s.session_time, from_location: s.from_location, to_location: s.to_location, session_type: s.session_type })),
        data: result.data,
      },
      message: formattedMessage,
      type: 'sessions_list',
      success: true,
    },
  }];
}

return [{ json: { ...item, type: item.type || (result.success ? 'receipt' : 'failed') } }];
